class MethodFrame {
    private Stack<String> outputFrameStack;

    public MethodFrame() {
        this.outputFrameStack = new Stack<>();
    }

    private void pop(final String descriptor) {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        if (descriptor.charAt(0) == '(') { // Method descriptor
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
        } else {
            popType(descriptor, 0);
        }
    }

    private int popType(final String descriptor, int index) {
        char desc = descriptor.charAt(index);
        switch (desc) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
            case 'L': // Object reference
                outputFrameStack.pop();
                break;
            case 'J': // Long or Double
                outputFrameStack.pop();
                outputFrameStack.pop();
                break;
            case '[': // Array
                index = popArrayType(descriptor, index);
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        return index + 1;
    }

    private int popArrayType(final String descriptor, int index) {
        while (descriptor.charAt(index) == '[') {
            index++;
        }
        return popType(descriptor, index) - 1;
    }
}

